contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address user) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(user != address(0), "zero user");
        require(address(this).balance >= 0, "insufficient balance");

        uint256 beforeUserBal = c.balances(user); if (__ESBMC_reverted()) return;
        uint256 beforeContractBal = address(c).balance;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 afterUserBal = c.balances(user); if (__ESBMC_reverted()) return;
        uint256 afterContractBal = address(c).balance;

        assert(afterContractBal <= beforeContractBal && afterUserBal <= beforeUserBal);
    }
}

